use libtmux::{IndexedHooks, ReplaceMode, TmuxText};
use std::collections::BTreeMap;

let guard = libtmux::test::TestServer::new().await?;
let server = guard.server();

// The indices are tmux's own and are sparse: removing one does not renumber
// the rest, so the map is keyed rather than positional.
let mut entries = BTreeMap::new();
entries.insert(0, TmuxText::from("display-message first"));
entries.insert(4, TmuxText::from("display-message fifth"));
server
    .set_hooks("after-new-window", &IndexedHooks::from(entries), ReplaceMode::Replace)
    .await?;

let hooks: IndexedHooks = server.hook("after-new-window").await?.expect("just written");
assert_eq!(hooks.len(), 2);
assert_eq!(hooks.indices().copied().collect::<Vec<_>>(), vec![0, 4]);

guard.shutdown().await?;

use libtmux::{IndexedHooks, ReplaceMode, TmuxText};
use std::collections::BTreeMap;

let guard = libtmux::test::TestServer::new().await?;
let server = guard.server();

let mut first = BTreeMap::new();
first.insert(0, TmuxText::from("display-message one"));
first.insert(1, TmuxText::from("display-message two"));
server
    .set_hooks("after-new-window", &IndexedHooks::from(first), ReplaceMode::Replace)
    .await?;

// `Merge` writes the indices it names and leaves the rest alone.
let mut second = BTreeMap::new();
second.insert(1, TmuxText::from("display-message replaced"));
server
    .set_hooks("after-new-window", &IndexedHooks::from(second), ReplaceMode::Merge)
    .await?;

let hooks = server.hook("after-new-window").await?.expect("just written");
assert_eq!(hooks.len(), 2);

guard.shutdown().await?;

use libtmux::OutputLimits;

// The default is roomy enough for a pane with a very long history.
assert_eq!(OutputLimits::default().stdout_bytes(), 32 * 1024 * 1024);

// Tighten it where the caller knows the answer is small.
let limits = OutputLimits::default().max_stdout_bytes(64 * 1024);
assert_eq!(limits.stdout_bytes(), 64 * 1024);

use libtmux::DispatchLimits;

let limits = DispatchLimits::default().max_in_flight(4);
assert_eq!(limits.in_flight(), 4);

use libtmux::ControlClientLimits;

let limits = ControlClientLimits::default().max_clients(4);
assert_eq!(limits.clients(), 4);

use libtmux::ControlLimits;

let limits = ControlLimits::default().max_line_bytes(4096);
assert_eq!(limits.line_bytes(), 4096);

use libtmux::{OptionKind, option_schema};

// `mouse` is a real flag: on or off.
assert_eq!(option_schema("mouse").map(OptionSchema::kind), Some(OptionKind::Flag));

// `status` looks like one and is not: it also accepts a count of status
// lines, so reading it as a boolean discards those values.
assert_eq!(option_schema("status").map(OptionSchema::kind), Some(OptionKind::Choice));

use libtmux::{OptionScope, option_schema};

// The scope says which handle can set an option, which is not guessable
// from the name: `mouse` is per-session, and `exit-empty` is server-wide.
assert!(option_schema("mouse").is_some_and(|o| o.accepts(OptionScope::Session)));
assert!(option_schema("exit-empty").is_some_and(|o| o.accepts(OptionScope::Server)));

// Some options live in two tables at once, and tmux takes a write at
// either. Asking for one scope would have to pick, and picking is wrong.
let remain = option_schema("remain-on-exit").expect("a documented option");
assert_eq!(remain.scopes(), [OptionScope::Window, OptionScope::Pane]);

use libtmux::{OptionKind, OptionScope, option_schema};

let schema = option_schema("history-limit").expect("a documented option");
assert_eq!(schema.name(), "history-limit");
assert_eq!(schema.kind(), OptionKind::Number);
assert_eq!(schema.scopes(), [OptionScope::Session]);
assert!(schema.accepts(OptionScope::Session));

// An option tmux does not have has no schema, which catches a typo before it
// reaches the server.
assert!(option_schema("history-limits").is_none());

use libtmux::{OptionKind, option_schema};

// `status` looks like a flag but accepts on, off, and 2 through 5, so
// tmux declares it a choice. The schema records that rather than guessing.
assert_eq!(option_schema("status").map(|o| o.kind()), Some(OptionKind::Choice));
assert_eq!(option_schema("mouse").map(|o| o.kind()), Some(OptionKind::Flag));
assert_eq!(option_schema("history-limit").map(|o| o.kind()), Some(OptionKind::Number));
assert_eq!(option_schema("after-new-window[0]").map(|o| o.kind()), Some(OptionKind::Command));
assert_eq!(option_schema("@mine"), None);

use libtmux::OptionValue;

let guard = libtmux::test::TestServer::new().await?;
let server = guard.server();
server.new_session("typed").await?;

// `mouse` is a flag, so `on` arrives as one.
let mouse = server.typed_global_option("mouse").await?.expect("mouse is set");
assert!(matches!(mouse, OptionValue::Flag(false)));

// `status` also reads `on`, and is *not* a flag: tmux accepts `on`, `off`,
// and `2` through `5`. Inferring the type from the value would call this a
// boolean and then fail on a value that is not one, which is why the
// schema is generated from tmux's own option table instead.
let status = server.typed_global_option("status").await?.expect("status is set");
assert!(matches!(status, OptionValue::Text(_)));

guard.shutdown().await?;

let guard = libtmux::test::TestServer::new().await?;
let session = guard.server().new_session("work").await?;
let window = session.active_window().await?.expect("a session has a window");
let pane = window.active_pane().await?.expect("a window has a pane");

pane.send_line("echo hello").await?;

// Capture returns `TmuxText`, because a pane can print any bytes.
let lines = pane.capture().await?;
assert!(!lines.is_empty());

guard.shutdown().await?;

use libtmux::Pane;

let session = server.new_session("locating").await?;
let expected = session.panes().await?.remove(0);

// Standing in for the environment tmux gives a process it starts.
let found = Pane::from_env_value(server, Some(expected.id().as_ref())).await?;

assert_eq!(found.expect("the pane exists").id(), expected.id());

use libtmux::{SplitDirection, SplitOptions};

let guard = libtmux::test::TestServer::new().await?;
let session = guard.server().new_session("edges").await?;
let mut window = session.active_window().await?.expect("a window");

// One pane fills the window, so it touches every edge.
let only = window.active_pane().await?.expect("a pane");
assert!(only.is_at_top() && only.is_at_bottom());

// Splitting below leaves the original touching the top and not the
// bottom, and the new one the other way round.
let lower = window.split(SplitOptions::new(SplitDirection::Below)).await?;
let upper = window
    .panes()
    .await?
    .into_iter()
    .find(|pane| pane.id() != lower.id())
    .expect("the original pane");

assert!(upper.is_at_top() && !upper.is_at_bottom());
assert!(lower.is_at_bottom() && !lower.is_at_top());

guard.shutdown().await?;

let guard = libtmux::test::TestServer::new().await?;
let session = guard.server().new_session("piped").await?;
let mut pane = session.panes().await?.remove(0);

assert!(!pane.is_piped());

pane.pipe(Some("cat >/dev/null")).await?;
pane.refresh().await?;
assert!(pane.is_piped());

pane.pipe(None::<String>).await?;
pane.refresh().await?;
assert!(!pane.is_piped());

use libtmux::{PaneSize, SplitDirection, SplitOptions};

let session = server.new_session("split-from-pane").await?;
let pane = session.panes().await?.remove(0);

